      const added = files.length ? await addFilesDeduped(files, metas) : 0;   // #253 skip an image already staged
      if (added) toast(`Added ${added} image${added > 1 ? 's' : ''} from ${(prov && prov.name) || 'provider'} ✓`);   // name the source in the log/toast
