  let gtDateRoles = (() => { try { const raw = GM_getValue('gt-date-roles', ''); if (raw) { const a = typeof raw === 'string' ? JSON.parse(raw) : raw; if (Array.isArray(a)) return a.map(String); } } catch (e) {} return DATE_ROLES_DEFAULT.slice(); })();
