    const help = p.querySelector('.mmth-s-help'); help.checked = !!SET.hideHelp;
    const ins = p.querySelector('.mmth-s-ins'); ins.value = SET.defaultInsert;
    const nl = p.querySelector('.mmth-s-nl'); nl.checked = SET.appendNewline !== false;
