        dv: (o.deltav != null && o.deltav !== '') ? +o.deltav : ((o.dv != null && o.dv !== '') ? +o.dv : ''),
        submit: !!(o.submit || o.enter), mbid: !!o.mbid, enable: o.enable !== false,   // legacy `enter` → submit
