    const fmtMarkerMode = GM_getValue('pc:format-marker', 'circle');
    providerModal.querySelectorAll('input[name="format-marker"]').forEach(r => { r.checked = r.value === fmtMarkerMode; });
    bpRefreshSetupUI();
